-- Django PostgreSQL auth schema with framework join tables and named FKs.
CREATE TABLE public.django_content_type (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY,
    app_label VARCHAR(100) NOT NULL,
    model VARCHAR(100) NOT NULL,
    CONSTRAINT django_content_type_pkey PRIMARY KEY (id),
    CONSTRAINT django_content_type_app_model_uniq UNIQUE (app_label, model)
);

CREATE TABLE public.auth_permission (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY,
    name VARCHAR(255) NOT NULL,
    content_type_id INTEGER NOT NULL,
    codename VARCHAR(100) NOT NULL,
    CONSTRAINT auth_permission_pkey PRIMARY KEY (id),
    CONSTRAINT auth_permission_content_type_codename_uniq UNIQUE (content_type_id, codename),
    CONSTRAINT auth_permission_content_type_fk
        FOREIGN KEY (content_type_id) REFERENCES public.django_content_type(id)
);

CREATE TABLE public.auth_group (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY,
    name VARCHAR(150) NOT NULL,
    CONSTRAINT auth_group_pkey PRIMARY KEY (id),
    CONSTRAINT auth_group_name_key UNIQUE (name)
);

CREATE TABLE public.auth_group_permissions (
    group_id BIGINT NOT NULL,
    permission_id BIGINT NOT NULL,
    CONSTRAINT auth_group_permissions_pkey PRIMARY KEY (group_id, permission_id),
    CONSTRAINT auth_group_permissions_group_fk
        FOREIGN KEY (group_id) REFERENCES public.auth_group(id),
    CONSTRAINT auth_group_permissions_permission_fk
        FOREIGN KEY (permission_id) REFERENCES public.auth_permission(id)
);

CREATE TABLE public.auth_user (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY,
    password VARCHAR(128) NOT NULL,
    last_login TIMESTAMPTZ,
    is_superuser BOOLEAN NOT NULL DEFAULT false,
    username VARCHAR(150) NOT NULL,
    first_name VARCHAR(150) NOT NULL DEFAULT '',
    last_name VARCHAR(150) NOT NULL DEFAULT '',
    email VARCHAR(254) NOT NULL,
    is_staff BOOLEAN NOT NULL DEFAULT false,
    is_active BOOLEAN NOT NULL DEFAULT true,
    date_joined TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT auth_user_pkey PRIMARY KEY (id),
    CONSTRAINT auth_user_username_key UNIQUE (username)
);

CREATE TABLE public.auth_user_groups (
    user_id BIGINT NOT NULL,
    group_id BIGINT NOT NULL,
    CONSTRAINT auth_user_groups_pkey PRIMARY KEY (user_id, group_id),
    CONSTRAINT auth_user_groups_user_fk
        FOREIGN KEY (user_id) REFERENCES public.auth_user(id),
    CONSTRAINT auth_user_groups_group_fk
        FOREIGN KEY (group_id) REFERENCES public.auth_group(id)
);

CREATE TABLE public.auth_user_user_permissions (
    user_id BIGINT NOT NULL,
    permission_id BIGINT NOT NULL,
    CONSTRAINT auth_user_user_permissions_pkey PRIMARY KEY (user_id, permission_id),
    CONSTRAINT auth_user_permissions_user_fk
        FOREIGN KEY (user_id) REFERENCES public.auth_user(id),
    CONSTRAINT auth_user_permissions_permission_fk
        FOREIGN KEY (permission_id) REFERENCES public.auth_permission(id)
);

CREATE INDEX auth_permission_content_type_idx ON public.auth_permission (content_type_id, codename);
CREATE INDEX auth_user_email_idx ON public.auth_user (email);
CREATE INDEX auth_user_groups_group_idx ON public.auth_user_groups (group_id);
